"""GraphQL documents used by the event feed and newer mutations."""

from __future__ import annotations

CHAT_UPDATED = "subscription chatUpdated($filter: ChatFilter, $showForbiddenImage: Boolean) {  chatUpdated(filter: $filter) {    ...ChatUpdatedFields    __typename  }}fragment ChatUpdatedFields on Chat {  id  unreadMessagesCounter  isTextingAllowed  lastMessage {    ...LastChatMessageFields    __typename  }  status  startedAt  finishedAt  __typename}fragment LastChatMessageFields on ChatMessage {  id  text  createdAt  isRead  isBulkMessaging  event  file {    ...RegularFile    __typename  }  user {    ...ChatMessageUserFields    __typename  }  eventByUser {    ...ChatMessageUserFields    __typename  }  eventToUser {    ...ChatMessageUserFields    __typename  }  deal {    ...ChatMessageItemDeal    __typename  }  __typename}fragment RegularFile on File {  id  url  filename  mime  __typename}fragment ChatMessageUserFields on UserFragment {  ...UserEdgeNode  __typename}fragment UserEdgeNode on UserFragment {  ...RegularUserFragment  __typename}fragment RegularUserFragment on UserFragment {  id  username  role  avatarURL  isOnline  isBlocked  rating  testimonialCounter  createdAt  supportChatId  systemChatId  __typename}fragment ChatMessageItemDeal on ItemDeal {  id  direction  status  statusDescription  hasProblem  props {    ...ItemDealProps    __typename  }  user {    ...ChatParticipant    __typename  }  testimonial {    ...ChatMessageDealTestimonial    __typename  }  item {    id    name    price    slug    rawPrice    sellerType    user {      ...ChatParticipant      __typename    }    category {      id      __typename    }    attachments(showForbiddenImage: $showForbiddenImage) {      ...PartialFile      __typename    }    isAttachmentsForbidden    comment    dataFields {      ...GameCategoryDataFieldWithValue      __typename    }    obtainingType {      ...GameCategoryObtainingType      __typename    }    __typename  }  obtainingFields {    ...GameCategoryDataFieldWithValue    __typename  }  automationObtainingFields {    ...ItemDealAutomationObtainingField    __typename  }  chat {    id    type    __typename  }  transaction {    id    statusExpirationDate    __typename  }  statusExpirationDate  commentFromBuyer  gameCategoryWarnings {    ...ItemDealWarningFragment    __typename  }  obtainingTypeWarnings {    ...ItemDealWarningFragment    __typename  }  __typename}fragment ItemDealProps on ItemDealProps {  autoConfirmPeriod  confirmationRestriction  confirmationRestrictionTexts {    sellerDealSubtitle    buyerDealSubtitle    buyerTimerText    __typename  }  __typename}fragment ChatParticipant on UserFragment {  ...RegularUserFragment  __typename}fragment ChatMessageDealTestimonial on Testimonial {  id  status  text  rating  createdAt  updatedAt  creator {    ...RegularUserFragment    __typename  }  moderator {    ...RegularUserFragment    __typename  }  user {    ...RegularUserFragment    __typename  }  __typename}fragment PartialFile on File {  id  url  __typename}fragment GameCategoryDataFieldWithValue on GameCategoryDataFieldWithValue {  id  label  type  inputType  copyable  hidden  required  value  __typename}fragment GameCategoryObtainingType on GameCategoryObtainingType {  id  name  stockType  description  gameCategoryId  noCommentFromBuyer  instructionForBuyer  instructionForSeller  sequence  feeMultiplier  agreements {    ...MinimalGameCategoryAgreement    __typename  }  props {    minTestimonialsForSeller    __typename  }  __typename}fragment MinimalGameCategoryAgreement on GameCategoryAgreement {  description  iconType  id  sequence  __typename}fragment ItemDealAutomationObtainingField on AutomationObtainingFieldItemDeals {  code  value  name  __typename}fragment ItemDealWarningFragment on ItemDealWarning {  id  status  title  text  __typename}"

USER_UPDATED = "subscription userUpdated($userId: UUID) {  userUpdated(userId: $userId) {    ...PartialUserProfile    __typename  }}fragment PartialUserProfile on UserProfile {  __typename  ...PartialUser  ...PartialUserFragment}fragment PartialUser on User {  id  unreadChatsCounter  __typename}fragment PartialUserFragment on UserFragment {  id  __typename}"

CHAT_MESSAGE_CREATED = "subscription chatMessageCreated($filter: ChatMessageWSFilter!, $showForbiddenImage: Boolean) {  chatMessageCreated(filter: $filter) {    ...RegularChatMessage    __typename  }}fragment RegularChatMessage on ChatMessage {  id  text  createdAt  deletedAt  isRead  isSuspicious  isBulkMessaging  game {    ...RegularGameProfile    __typename  }  file {    ...PartialFile    __typename  }  user {    ...ChatMessageUserFields    __typename  }  deal {    ...ChatMessageItemDeal    __typename  }  item {    ...ItemEdgeNode    __typename  }  transaction {    ...RegularTransaction    __typename  }  moderator {    ...UserEdgeNode    __typename  }  eventByUser {    ...ChatMessageUserFields    __typename  }  eventToUser {    ...ChatMessageUserFields    __typename  }  isAutoResponse  event  buttons {    ...ChatMessageButton    __typename  }  images {    ...RegularFile    __typename  }  imageLinks  uncensorInfo {    count    lastEvent {      username      createdAt      __typename    }    __typename  }  plTokenAmount  __typename}fragment RegularGameProfile on GameProfile {  id  name  type  slug  logo {    ...PartialFile    __typename  }  __typename}fragment PartialFile on File {  id  url  __typename}fragment ChatMessageUserFields on UserFragment {  ...UserEdgeNode  __typename}fragment UserEdgeNode on UserFragment {  ...RegularUserFragment  __typename}fragment RegularUserFragment on UserFragment {  id  username  role  avatarURL  isOnline  isBlocked  rating  testimonialCounter  createdAt  supportChatId  systemChatId  __typename}fragment ChatMessageItemDeal on ItemDeal {  id  direction  status  statusDescription  hasProblem  props {    ...ItemDealProps    __typename  }  user {    ...ChatParticipant    __typename  }  testimonial {    ...ChatMessageDealTestimonial    __typename  }  item {    id    name    price    slug    rawPrice    sellerType    user {      ...ChatParticipant      __typename    }    category {      id      __typename    }    attachments(showForbiddenImage: $showForbiddenImage) {      ...PartialFile      __typename    }    isAttachmentsForbidden    comment    dataFields {      ...GameCategoryDataFieldWithValue      __typename    }    obtainingType {      ...GameCategoryObtainingType      __typename    }    __typename  }  obtainingFields {    ...GameCategoryDataFieldWithValue    __typename  }  automationObtainingFields {    ...ItemDealAutomationObtainingField    __typename  }  chat {    id    type    __typename  }  transaction {    id    statusExpirationDate    __typename  }  statusExpirationDate  commentFromBuyer  gameCategoryWarnings {    ...ItemDealWarningFragment    __typename  }  obtainingTypeWarnings {    ...ItemDealWarningFragment    __typename  }  __typename}fragment ItemDealProps on ItemDealProps {  autoConfirmPeriod  confirmationRestriction  confirmationRestrictionTexts {    sellerDealSubtitle    buyerDealSubtitle    buyerTimerText    __typename  }  __typename}fragment ChatParticipant on UserFragment {  ...RegularUserFragment  __typename}fragment ChatMessageDealTestimonial on Testimonial {  id  status  text  rating  createdAt  updatedAt  creator {    ...RegularUserFragment    __typename  }  moderator {    ...RegularUserFragment    __typename  }  user {    ...RegularUserFragment    __typename  }  __typename}fragment GameCategoryDataFieldWithValue on GameCategoryDataFieldWithValue {  id  label  type  inputType  copyable  hidden  required  value  __typename}fragment GameCategoryObtainingType on GameCategoryObtainingType {  id  name  stockType  description  gameCategoryId  noCommentFromBuyer  instructionForBuyer  instructionForSeller  sequence  feeMultiplier  agreements {    ...MinimalGameCategoryAgreement    __typename  }  props {    minTestimonialsForSeller    __typename  }  __typename}fragment MinimalGameCategoryAgreement on GameCategoryAgreement {  description  iconType  id  sequence  __typename}fragment ItemDealAutomationObtainingField on AutomationObtainingFieldItemDeals {  code  value  name  __typename}fragment ItemDealWarningFragment on ItemDealWarning {  id  status  title  text  __typename}fragment ItemEdgeNode on ItemProfile {  ...MyItemEdgeNode  ...ForeignItemEdgeNode  __typename}fragment MyItemEdgeNode on MyItemProfile {  id  slug  priority  status  name  price  rawPrice  statusExpirationDate  sellerType  attachment(showForbiddenImage: $showForbiddenImage) {    ...PartialFile    __typename  }  isAttachmentsForbidden  user {    ...UserItemEdgeNode    __typename  }  game {    name    __typename  }  category {    name    __typename  }  approvalDate  createdAt  priorityPosition  viewsCounter  dealsCounter  keepInSale  feeMultiplier  isAutomated  __typename}fragment UserItemEdgeNode on UserFragment {  ...UserEdgeNode  __typename}fragment ForeignItemEdgeNode on ForeignItemProfile {  id  slug  priority  status  name  price  rawPrice  sellerType  attachment(showForbiddenImage: $showForbiddenImage) {    ...PartialFile    __typename  }  isAttachmentsForbidden  user {    ...UserItemEdgeNode    __typename  }  game {    name    __typename  }  category {    name    __typename  }  approvalDate  priorityPosition  createdAt  viewsCounter  dealsCounter  feeMultiplier  isAutomated  __typename}fragment RegularTransaction on Transaction {  id  operation  direction  providerId  provider {    ...RegularTransactionProvider    __typename  }  user {    ...RegularUserFragment    __typename  }  creator {    ...RegularUserFragment    __typename  }  status  statusDescription  statusExpirationDate  value  fee  createdAt  props {    ...RegularTransactionProps    __typename  }  verifiedAt  verifiedBy {    ...UserEdgeNode    __typename  }  completedBy {    ...UserEdgeNode    __typename  }  paymentMethodId  completedAt  isSuspicious  spbBankName  autoClaimedAt  __typename}fragment RegularTransactionProvider on TransactionProvider {  id  name  fee  minFeeAmount  description  account {    ...RegularTransactionProviderAccount    __typename  }  props {    ...TransactionProviderPropsFragment    __typename  }  limits {    ...ProviderLimits    __typename  }  paymentMethods {    ...TransactionPaymentMethod    __typename  }  __typename}fragment RegularTransactionProviderAccount on TransactionProviderAccount {  id  value  userId  providerId  paymentMethodId  __typename}fragment TransactionProviderPropsFragment on TransactionProviderPropsFragment {  requiredUserData {    ...TransactionProviderRequiredUserData    __typename  }  tooltip  __typename}fragment TransactionProviderRequiredUserData on TransactionProviderRequiredUserData {  email  phoneNumber  eripAccountNumber  __typename}fragment ProviderLimits on ProviderLimits {  incoming {    ...ProviderLimitRange    __typename  }  outgoing {    ...ProviderLimitRange    __typename  }  __typename}fragment ProviderLimitRange on ProviderLimitRange {  min  max  __typename}fragment TransactionPaymentMethod on TransactionPaymentMethod {  id  name  fee  providerId  account {    ...RegularTransactionProviderAccount    __typename  }  props {    ...TransactionProviderPropsFragment    __typename  }  limits {    ...ProviderLimits    __typename  }  __typename}fragment RegularTransactionProps on TransactionPropsFragment {  creatorId  dealId  paidFromPendingIncome  paymentURL  successURL  fee  paymentAccount {    id    value    __typename  }  paymentGateway  alreadySpent  exchangeRate  amountAfterConversionRub  amountAfterConversionUsdt  fragmentUsername  userData {    account    email    ipAddress    phoneNumber    __typename  }  __typename}fragment ChatMessageButton on ChatMessageButton {  type  url  text  __typename}fragment RegularFile on File {  id  url  filename  mime  __typename}"

UPLOAD_CHAT_IMAGE = "mutation uploadChatImageIntoTemporaryStore($file: Upload!, $input: UploadTemporaryAttachmentInput!) {\n  uploadChatImageIntoTemporaryStore(file: $file, input: $input) {\n    expiresAt\n    id\n    url\n    chatId\n    clientAttachmentId\n    __typename\n  }\n}"

REPORT_DEAL_PROBLEM = "mutation reportDealProblem($input: ReportDealProblemInput!, $showForbiddenImage: Boolean) {\n  reportDealProblem(input: $input) {\n    ...RegularItemDeal\n    __typename\n  }\n}\n\nfragment RegularItemDeal on ItemDeal {\n  id\n  status\n  direction\n  statusExpirationDate\n  statusDescription\n  obtaining\n  hasProblem\n  reportProblemEnabled\n  completedBy {\n    ...MinimalUserFragment\n    __typename\n  }\n  props {\n    ...ItemDealProps\n    __typename\n  }\n  prevStatus\n  completedAt\n  createdAt\n  logs {\n    ...ItemLog\n    __typename\n  }\n  transaction {\n    ...ItemDealTransaction\n    __typename\n  }\n  user {\n    ...UserEdgeNode\n    __typename\n  }\n  chat {\n    ...RegularChatId\n    __typename\n  }\n  item {\n    ...PartialDealItem\n    __typename\n  }\n  testimonial {\n    ...RegularItemDealTestimonial\n    __typename\n  }\n  obtainingFields {\n    ...GameCategoryDataFieldWithValue\n    __typename\n  }\n  commentFromBuyer\n  __typename\n}\n\nfragment MinimalUserFragment on UserFragment {\n  id\n  username\n  role\n  __typename\n}\n\nfragment ItemDealProps on ItemDealProps {\n  autoConfirmPeriod\n  __typename\n}\n\nfragment ItemLog on ItemLog {\n  id\n  event\n  createdAt\n  user {\n    ...UserEdgeNode\n    __typename\n  }\n  __typename\n}\n\nfragment UserEdgeNode on UserFragment {\n  ...RegularUserFragment\n  __typename\n}\n\nfragment RegularUserFragment on UserFragment {\n  id\n  username\n  role\n  avatarURL\n  isOnline\n  isBlocked\n  rating\n  testimonialCounter\n  createdAt\n  supportChatId\n  systemChatId\n  __typename\n}\n\nfragment ItemDealTransaction on Transaction {\n  id\n  operation\n  direction\n  providerId\n  status\n  value\n  createdAt\n  paymentMethodId\n  statusExpirationDate\n  __typename\n}\n\nfragment RegularChatId on Chat {\n  id\n  __typename\n}\n\nfragment PartialDealItem on Item {\n  ...PartialDealMyItem\n  ...PartialDealForeignItem\n  __typename\n}\n\nfragment PartialDealMyItem on MyItem {\n  id\n  slug\n  priority\n  status\n  name\n  price\n  priorityPrice\n  rawPrice\n  statusExpirationDate\n  sellerType\n  approvalDate\n  createdAt\n  priorityPosition\n  viewsCounter\n  feeMultiplier\n  comment\n  attachments(showForbiddenImage: $showForbiddenImage) {\n    ...RegularFile\n    __typename\n  }\n  isAttachmentsForbidden\n  user {\n    ...UserEdgeNode\n    __typename\n  }\n  game {\n    ...RegularGameProfile\n    __typename\n  }\n  category {\n    ...MinimalGameCategory\n    __typename\n  }\n  dataFields {\n    ...GameCategoryDataFieldWithValue\n    __typename\n  }\n  obtainingType {\n    ...MinimalGameCategoryObtainingType\n    __typename\n  }\n  __typename\n}\n\nfragment RegularFile on File {\n  id\n  url\n  filename\n  mime\n  __typename\n}\n\nfragment RegularGameProfile on GameProfile {\n  id\n  name\n  type\n  slug\n  logo {\n    ...PartialFile\n    __typename\n  }\n  __typename\n}\n\nfragment PartialFile on File {\n  id\n  url\n  __typename\n}\n\nfragment MinimalGameCategory on GameCategory {\n  id\n  slug\n  name\n  __typename\n}\n\nfragment GameCategoryDataFieldWithValue on GameCategoryDataFieldWithValue {\n  id\n  label\n  type\n  inputType\n  copyable\n  hidden\n  required\n  value\n  __typename\n}\n\nfragment MinimalGameCategoryObtainingType on GameCategoryObtainingType {\n  id\n  name\n  description\n  gameCategoryId\n  noCommentFromBuyer\n  instructionForBuyer\n  instructionForSeller\n  sequence\n  feeMultiplier\n  props {\n    minTestimonialsForSeller\n    __typename\n  }\n  __typename\n}\n\nfragment PartialDealForeignItem on ForeignItem {\n  id\n  slug\n  priority\n  status\n  name\n  price\n  rawPrice\n  sellerType\n  approvalDate\n  priorityPosition\n  createdAt\n  viewsCounter\n  feeMultiplier\n  comment\n  attachments(showForbiddenImage: $showForbiddenImage) {\n    ...RegularFile\n    __typename\n  }\n  isAttachmentsForbidden\n  user {\n    ...UserEdgeNode\n    __typename\n  }\n  game {\n    ...RegularGameProfile\n    __typename\n  }\n  category {\n    ...MinimalGameCategory\n    __typename\n  }\n  dataFields {\n    ...GameCategoryDataFieldWithValue\n    __typename\n  }\n  obtainingType {\n    ...MinimalGameCategoryObtainingType\n    __typename\n  }\n  __typename\n}\n\nfragment RegularItemDealTestimonial on Testimonial {\n  id\n  status\n  text\n  rating\n  createdAt\n  updatedAt\n  creator {\n    ...RegularUserFragment\n    __typename\n  }\n  moderator {\n    ...RegularUserFragment\n    __typename\n  }\n  user {\n    ...RegularUserFragment\n    __typename\n  }\n  __typename\n}"
